func (q *Queries) UpdateMessageBody(ctx context.Context, arg UpdateMessageBodyParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, updateMessageBody, arg.Body, arg.ID, arg.AuthorUserID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}
